def nand(a, b): return 1 - (a & b)
def not_(a):    return nand(a, a)
def and_(a, b): return not_(nand(a, b))
def or_(a, b):  return nand(not_(a), not_(b))
def xor(a, b):  return and_(or_(a, b), nand(a, b))

def full_adder(a, b, c):
    s1, c1 = xor(a, b), and_(a, b)
    return xor(s1, c), or_(c1, and_(s1, c))

def add4(x, y):            # bit lists, least significant first
    out, carry = [], 0
    for a, b in zip(x, y):
        s, carry = full_adder(a, b, carry)
        out.append(s)
    return out

print(add4([1, 1, 0, 0], [1, 0, 1, 0]))   # 3 + 5 = 8 -> [0, 0, 0, 1]

