#define N 4096
static int a[N][N];   /* 64 MiB, far bigger than any cache */

int main(void) {
    long sum = 0;
    clock_t t = clock();
    for (int i = 0; i < N; i++)       /* row by row: sequential */
        for (int j = 0; j < N; j++) sum += a[i][j];
    printf("rows: %.3fs\n", (double)(clock() - t) / CLOCKS_PER_SEC);
    t = clock();
    for (int j = 0; j < N; j++)       /* column by column: stride 16 KiB */
        for (int i = 0; i < N; i++) sum += a[i][j];
    printf("cols: %.3fs (sum %ld)\n", (double)(clock() - t) / CLOCKS_PER_SEC, sum);
    return 0;
}

#include <stddef.h>
#include <stdint.h>

#define ALIGN16(n) (((n) + 15) & ~(size_t)15)

static _Alignas(16) uint8_t arena[1 << 20];   /* 1 MiB pretend heap */
static size_t top = 0;

/* Bump allocator: the simplest possible malloc. free() is a no-op. */
void *bump_malloc(size_t n) {
    size_t need = ALIGN16(n);
    if (need < n || need > sizeof arena - top) return NULL;  /* overflow or full */
    void *p = &arena[top];
    top += need;
    return p;
}

