#include <pthread.h>

struct account { int id; long balance; pthread_mutex_t lock; };

void transfer(struct account *from, struct account *to, long amount) {
    struct account *first  = from->id < to->id ? from : to;   /* global order */
    struct account *second = from->id < to->id ? to : from;
    pthread_mutex_lock(&first->lock);
    pthread_mutex_lock(&second->lock);
    if (from->balance >= amount) {
        from->balance -= amount;
        to->balance += amount;
    }
    pthread_mutex_unlock(&second->lock);
    pthread_mutex_unlock(&first->lock);
}

#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdio.h>

static int data;                       /* plain, non-atomic payload */
static atomic_bool ready = false;

static void *producer(void *arg) {
    (void)arg;
    data = 42;                                            /* 1: write payload */
    atomic_store_explicit(&ready, true, memory_order_release);  /* 2: publish */
    return NULL;
}

int main(void) {
    pthread_t t;
    pthread_create(&t, NULL, producer, NULL);
    while (!atomic_load_explicit(&ready, memory_order_acquire))
        ;                                                 /* spin until published */
    printf("%d\n", data);                                 /* guaranteed 42 */
    pthread_join(t, NULL);
    return 0;
}

